from dataclasses import dataclass, field


@dataclass
class OrderLine:
    sku: str
    qty: int
    unit_cents: int

    @property
    def total_cents(self) -> int:
        return self.qty * self.unit_cents


@dataclass
class Order:
    id: str
    lines: list[OrderLine] = field(default_factory=list)
    currency: str = "USD"
    discount_percent: int = 0

    def __post_init__(self) -> None:
        if not 0 <= self.discount_percent <= 100:
            raise ValueError("discount_percent must be between 0 and 100")

    @property
    def discount_cents(self) -> int:
        """Discount amount in cents: the percentage of the subtotal, rounded down."""
        return (sum(line.total_cents for line in self.lines) * self.discount_percent) // 100

    @property
    def subtotal_cents(self) -> int:
        return sum(line.total_cents for line in self.lines)

    @property
    def total_cents(self) -> int:
        """Order total in cents, after the percentage discount.
        The discount amount is the percentage of the subtotal, rounded down to whole cents."""
        discount = self.discount_cents
        return self.subtotal_cents - discount

